#include <errno.h>
#include <stdbool.h>
#include <stdint.h>
#include <string.h>
#include <zephyr/device.h>
#include <zephyr/drivers/firmware/qemu_fwcfg/qemu_fwcfg.h>
#include <zephyr/kernel.h>
#include <zephyr/logging/log.h>
#include <zephyr/sys/byteorder.h>

#include "qemu_fwcfg.h"

LOG_MODULE_REGISTER(qemu_fwcfg, CONFIG_QEMU_FWCFG_LOG_LEVEL);

#define FW_CFG_SIGNATURE     0x0000
#define FW_CFG_ID            0x0001
#define FW_CFG_FILE_DIR      0x0019

#define FW_CFG_DMA_CTL_ERROR  0x01
#define FW_CFG_DMA_CTL_READ   0x02
#define FW_CFG_DMA_CTL_SKIP   0x04
#define FW_CFG_DMA_CTL_SELECT 0x08
#define FW_CFG_DMA_CTL_WRITE  0x10

struct fwcfg_file {
	uint32_t size;
	uint16_t select;
	uint16_t reserved;
	char name[56];
} __packed;

struct fwcfg_dma_access {
	uint32_t control;
	uint32_t length;
	uint64_t address;
} __packed;

static int fwcfg_select_Key(const struct device *dev, uint16_t key)
{
	const struct qemu_fwcfg_config *config = dev->config;

	return config->api->select(dev, key);
}

static int fwcfg_read_bytes(const struct device *dev, void *buf, size_t len)
{
	const struct qemu_fwcfg_config *config = dev->config;

	return config->api->read(dev, buf, len);
}

static int fwcfg_dma_xfer(const struct device *dev, uint32_t control, void *buf, uint32_t len)
{
	const struct qemu_fwcfg_config *config = dev->config;
	volatile struct fwcfg_dma_access acc __aligned(8);
	int rc;

	acc.control = sys_cpu_to_be32(control);
	acc.length = sys_cpu_to_be32(len);
	acc.address = sys_cpu_to_be64((uintptr_t)buf);

	/* Barrier to ensure structure writes complete before telling device */
	barrier_dmem_fence_full();

	rc = config->api->write_dma(dev, (uintptr_t)&acc);
	if (rc != 0) {
		return rc;
	}

	while ((sys_be32_to_cpu(acc.control) & ~FW_CFG_DMA_CTL_ERROR) != 0) {
		barrier_dmem_fence_full();
	}

	if ((sys_be32_to_cpu(acc.control) & FW_CFG_DMA_CTL_ERROR) != 0) {
		return -EIO;
	}

	return 0;
}

static int fwcfg_read_item_pio(const struct device *dev, uint16_t key, void *buf, size_t len)
{
	int rc;

	rc = fwcfg_select_Key(dev, key);
	if (rc != 0) {
		return rc;
	}

	return fwcfg_read_bytes(dev, buf, len);
}

static int fwcfg_read_item_dma(const struct device *dev, uint16_t key, void *buf, size_t len)
{
	uint32_t control = ((uint32_t)key << 16) | FW_CFG_DMA_CTL_SELECT | FW_CFG_DMA_CTL_READ;

	return fwcfg_dma_xfer(dev, control, buf, len);
}

int qemu_fwcfg_read_item(const struct device *dev, uint16_t key, void *buf, size_t len)
{
	struct qemu_fwcfg_data *data = dev->data;
	int rc;

	(void)k_mutex_lock(&data->lock, K_FOREVER);
	if (qemu_fwcfg_dma_supported(dev)) {
		rc = fwcfg_read_item_dma(dev, key, buf, len);
	} else {
		rc = fwcfg_read_item_pio(dev, key, buf, len);
	}
	k_mutex_unlock(&data->lock);

	return rc;
}

int qemu_fwcfg_write_item(const struct device *dev, uint16_t key, const void *buf, size_t len)
{
	struct qemu_fwcfg_data *data = dev->data;
	uint32_t control = ((uint32_t)key << 16) | FW_CFG_DMA_CTL_SELECT | FW_CFG_DMA_CTL_WRITE;
	int rc;

	if (!qemu_fwcfg_dma_supported(dev)) {
		return -ENOTSUP;
	}

	(void)k_mutex_lock(&data->lock, K_FOREVER);
	/* Cast away const: FW_CFG_DMA_CTL_WRITE does not modify buffer */
	rc = fwcfg_dma_xfer(dev, control, (void *)buf, len);
	k_mutex_unlock(&data->lock);

	return rc;
}

uint32_t qemu_fwcfg_get_features(const struct device *dev)
{
	struct qemu_fwcfg_data *data = dev->data;

	return data->features;
}

bool qemu_fwcfg_dma_supported(const struct device *dev)
{
	struct qemu_fwcfg_data *data = dev->data;

	return (data->features & FW_CFG_F_DMA) != 0;
}

int qemu_fwcfg_find_file(const struct device *dev, const char *file, uint16_t *select,
			 uint32_t *size)
{
	struct qemu_fwcfg_data *data = dev->data;
	uint32_t count;
	int rc;

	(void)k_mutex_lock(&data->lock, K_FOREVER);

	if (qemu_fwcfg_dma_supported(dev)) {
		uint32_t control =
			(FW_CFG_FILE_DIR << 16) | FW_CFG_DMA_CTL_SELECT | FW_CFG_DMA_CTL_READ;

		rc = fwcfg_dma_xfer(dev, control, &count, sizeof(count));
	} else {
		rc = fwcfg_read_item_pio(dev, FW_CFG_FILE_DIR, &count, sizeof(count));
	}

	if (rc != 0) {
		k_mutex_unlock(&data->lock);
		return rc;
	}

	count = sys_be32_to_cpu(count);

	for (uint32_t i = 0; i < count; i++) {
		struct fwcfg_file entry;

		if (qemu_fwcfg_dma_supported(dev)) {
			rc = fwcfg_dma_xfer(dev, FW_CFG_DMA_CTL_READ, &entry, sizeof(entry));
		} else {
			rc = fwcfg_read_bytes(dev, &entry, sizeof(entry));
		}

		if (rc != 0) {
			k_mutex_unlock(&data->lock);
			return rc;
		}

		if (strcmp(entry.name, file) == 0) {
			*select = sys_be16_to_cpu(entry.select);
			*size = sys_be32_to_cpu(entry.size);
			k_mutex_unlock(&data->lock);
			return 0;
		}
	}

	k_mutex_unlock(&data->lock);
	return -ENOENT;
}

int qemu_fwcfg_init(const struct device *dev)
{
	struct qemu_fwcfg_data *data = dev->data;
	uint8_t sig[4];
	uint32_t id;
	int rc;

	rc = k_mutex_init(&data->lock);
	if (rc != 0) {
		return rc;
	}

	rc = fwcfg_read_item_pio(dev, FW_CFG_SIGNATURE, sig, sizeof(sig));
	if (rc != 0) {
		LOG_ERR("Failed to read signature: %d", rc);
		return rc;
	}

	if (memcmp(sig, "QEMU", 4) != 0) {
		LOG_ERR("Invalid signature: 0x%02x%02x%02x%02x", sig[0], sig[1], sig[2], sig[3]);
		return -ENODEV;
	}

	rc = fwcfg_read_item_pio(dev, FW_CFG_ID, &id, sizeof(id));
	if (rc != 0) {
		LOG_ERR("Failed to read ID: %d", rc);
		return rc;
	}

	data->features = sys_le32_to_cpu(id);
	LOG_INF("QEMU fw_cfg initialized, features: 0x%08x", data->features);

	return 0;
}
